T = TreeNode

def test_valid():
    assert is_bst(T(5, T(3, T(1), T(4)), T(8, T(6), T(9)))) is True

def test_deep_violation():
    assert is_bst(T(5, T(3), T(8, T(4), T(9)))) is False

def test_empty_and_single():
    assert is_bst(None) is True
    assert is_bst(T(42)) is True

def test_duplicates_invalid():
    assert is_bst(T(2, T(2), None)) is False
    assert is_bst(T(2, None, T(2))) is False

def test_negative_and_extreme_values():
    assert is_bst(T(0, T(-2**40), T(2**40))) is True
    assert is_bst(T(-1, None, T(-5))) is False
